5 |   const allowed = LOCAL.has(action);
6 |   return { allowed, authorizesRealWorld: false, risk: allowed ? 'LOCAL_BOUNDED' : 'EXTERNAL_OR_UNKNOWN', reason: allowed ? 'Local workflow only; existing permissions, STOP and evidence gates still apply.' : 'BLOCKED: no authenticated approval system or external execution adapter.' };
7 | }
8 | const ROUTES = Object.freeze({ '/api/start': 'research', '/api/decision': 'propose', '/api/world': 'research', '/api/discover': 'research', '/api/decide': 'record-review', '/api/stop': 'stop', '/api/resume': 'resume', '/api/export': 'export-local' });

1 | const test = require('node:test');
2 | const assert = require('node:assert/strict');
3 | const fs = require('node:fs');
4 | const vm = require('node:vm');
5 | 
6 | test('committed corridor matches source assembly exactly', () => {
7 |   const expected = require('../scripts/lib/corridor-build.cjs').assemble(fs.readFileSync('src/template.html', 'utf8'), fs.readFileSync('src/engine.js', 'utf8'), fs.readFileSync('src/app.js', 'utf8'));
