const fs=require('fs');
const {assemble}=require('./scripts/lib/corridor-build.cjs');
const t=fs.readFileSync('src/template.html','utf8');
const out=assemble(t,fs.readFileSync('src/engine.js','utf8'),fs.readFileSync('src/app.js','utf8'));
fs.writeFileSync('corridor.html',out); console.log('built',out.length,'bytes');

// CORE — agent motion and population rendering (Phase 8).
// Every registered profile is discoverable. Phase 9: agents stay at their virtual post unless a source gives them a
// reason to move — no random wandering. Motion sources, always labelled:
//   • recorded activity — trips driven by recorded autonomous missions (src/civ-activity.js): to the cited evidence
//     location and back, on the validated pedestrian network (OSM walkways that cross no building footprint);
//   • replay — positions driven by agents-world.js from a recorded mission log;
//   • live — on the founder's machine only, agents of tasks the local supervisor is actually running
//     (.core-local/live.json, never fetched on the public site).
// Rendering by zoom: < 13.5 zone aggregates; 13.5–15.8 WebGL figures; ≥ 15.8 articulated DOM avatars for agents
// in view (capped). The loop pauses when the tab is hidden; reduced motion freezes positions.
(function () {
  'use strict';
  const G = globalThis, POP = () => G.CORE_POPULATION;

// Constitution V1: local workflow permissions are never real-world authorization.
export const AUTHORITY = Object.freeze({ constitution: '1.0', externalActionsEnabled: false, authenticatedApprovalSystem: false, reviewerLabelsAreIdentity: false });
const LOCAL = new Set(['research', 'simulate', 'propose', 'critique', 'revise', 'record-review', 'stop', 'resume', 'export-local']);
export function authorityGate(action) {
  const allowed = LOCAL.has(action);
  return { allowed, authorizesRealWorld: false, risk: allowed ? 'LOCAL_BOUNDED' : 'EXTERNAL_OR_UNKNOWN', reason: allowed ? 'Local workflow only; existing permissions, STOP and evidence gates still apply.' : 'BLOCKED: no authenticated approval system or external execution adapter.' };
}
const ROUTES = Object.freeze({ '/api/start': 'research', '/api/decision': 'propose', '/api/world': 'research', '/api/discover': 'research', '/api/decide': 'record-review', '/api/stop': 'stop', '/api/resume': 'resume', '/api/export': 'export-local' });

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');

test('committed corridor matches source assembly exactly', () => {
  const expected = require('../scripts/lib/corridor-build.cjs').assemble(fs.readFileSync('src/template.html', 'utf8'), fs.readFileSync('src/engine.js', 'utf8'), fs.readFileSync('src/app.js', 'utf8'));
  assert.equal(fs.readFileSync('corridor.html', 'utf8'), expected);
});

test('inline scripts in both pages parse as JavaScript', () => {
  for (const file of ['index.html', 'corridor.html']) {
    const html = fs.readFileSync(file, 'utf8');
    for (const script of html.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/g)) {
      new vm.Script(script[1], { filename: file });
    }
  }
});
